<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class LegacyImportBatch extends Model { protected $guarded=[]; protected $casts=['analysis'=>'array','conflicts'=>'array','result'=>'array','cutover_checklist'=>'array','monitoring_report'=>'array','resume_checkpoint'=>'array','readiness_report'=>'array','evidence_manifest'=>'array','analyzed_at'=>'datetime','started_at'=>'datetime','finished_at'=>'datetime','committed_at'=>'datetime','cutover_approved_at'=>'datetime','monitoring_checked_at'=>'datetime','readiness_checked_at'=>'datetime','checkpoint_at'=>'datetime','migration_closed_at'=>'datetime','evidence_archived_at'=>'datetime','rolled_back_at'=>'datetime','archived_at'=>'datetime']; public function clinic(){return $this->belongsTo(Clinic::class);} public function creator(){return $this->belongsTo(User::class,'created_by');} public function cutoverApprover(){return $this->belongsTo(User::class,'cutover_approved_by');} public function monitoringChecker(){return $this->belongsTo(User::class,'monitoring_checked_by');} }
